/* Flash cards USMLE: Renal (429 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["renal"] = [{"name":"Physiology","cards":[["l1gc6d15w","What is the 60-40-20 rule of body fluids?","Total body water is 60% of body weight; ICF is 40%, ECF is 20% (plasma 1/4, interstitial 3/4 of ECF).","Regra 60-40-20."],["1ck33z8go","Which marker measures plasma volume?","Radiolabeled albumin.","Albumina marcada."],["1pfvq1c1y","Which marker measures extracellular volume?","Inulin or mannitol.","Inulina."],["hfao6x79g","What is the normal plasma osmolality?","About 285-295 mOsm/kg.","285 a 295 mOsm/kg."],["1pkjexnw2","How is plasma osmolality estimated?","2 x Na+ + glucose/18 + BUN/2.8.","Fórmula da osmolalidade."],["9yh0xwb89","What is glomerular filtration rate?","Rate of plasma filtered by glomeruli per minute; normal about 100-125 mL/min.","Taxa de filtração glomerular."],["19kx4lkqk","Why is inulin the gold standard for GFR?","Freely filtered, neither reabsorbed nor secreted.","Só filtrada."],["h89k46419","Why does creatinine slightly overestimate GFR?","Creatinine is slightly secreted by the PCT.","Um pouco é secretada."],["1m9tadees","What is the formula for renal clearance?","Cx = (Ux x V) / Px.","Fórmula de depuração."],["sxv4el1g2","What does clearance less than GFR indicate?","Net tubular reabsorption of the substance.","Reabsorção."],["ak5j7a1xk","What does clearance greater than GFR indicate?","Net tubular secretion.","Secreção."],["1l7vinszd","What substance measures effective renal plasma flow?","Para-aminohippuric acid (PAH), filtered and secreted.","PAH."],["aqupbsv8z","What is filtration fraction?","GFR / RPF; normally about 20%.","Fração de filtração cerca de 20%."],["qhupti1up","What are the Starling forces in the glomerulus?","GFR = Kf [(PGC - PBS) - (πGC - πBS)]; πBS normally zero.","Forças de Starling no glomérulo."],["7kw9vb15k","What is the effect of afferent arteriole constriction (e.g., NSAIDs)?","Decreased RPF and GFR; FF unchanged.","Reduz fluxo e filtração."],["19h3y621g","What is the effect of efferent arteriole constriction (angiotensin II)?","Decreased RPF, increased GFR, increased FF.","Aumenta a filtração."],["1es9blbsi","What is the effect of ACE inhibitors on GFR?","Dilate efferent arteriole: decrease GFR (and FF), increased RPF slightly.","Reduzem a filtração."],["1f00pzaos","What is the effect of increased plasma protein on GFR?","Decreases GFR (increased glomerular oncotic pressure).","Reduz a filtração."],["131d82pb3","What is the effect of ureteral obstruction on GFR?","Decreases GFR (increased Bowman space pressure).","Reduz a filtração."],["o4i91z1h3","What is the effect of dehydration on FF?","Increased FF (protein concentration rises, efferent constriction).","Aumenta a fração de filtração."],["ejj5wlfe7","What is the renal handling of glucose?","Freely filtered, reabsorbed in PCT by SGLT2 (and SGLT1); glucosuria begins at plasma glucose ~200 mg/dL (threshold), transport maximum at ~375 mg/dL.","Reabsorvida no túbulo proximal."],["5jk05x1gr","Why does pregnancy cause glucosuria?","Increased GFR and decreased reabsorption threshold.","Maior filtração."],["1eix2bdht","What is reabsorbed in the proximal convoluted tubule?","All glucose and amino acids, most HCO3-, Na+, Cl-, PO43-, K+, water, uric acid; generates NH3 from glutamine.","Glicose, aminoácidos, bicarbonato e sódio."],["l24nkjuxj","What does PTH do in the PCT?","Inhibits Na+/PO4 cotransport, increasing phosphate excretion.","Aumenta excreção de fosfato."],["btaomyscz","What does angiotensin II do in the PCT?","Stimulates Na+/H+ exchange, increasing Na+, water, HCO3- reabsorption (contraction alkalosis).","Aumenta reabsorção de sódio."],["q2i3rh1jt","What is the role of the thin descending loop of Henle?","Passively reabsorbs water (impermeable to Na+); concentrating segment.","Reabsorve água."],["vq7vxn1g4","What is the role of the thick ascending loop of Henle?","Reabsorbs Na+, K+, Cl- (NKCC2) and indirectly Mg2+ and Ca2+ (paracellular); impermeable to water; diluting segment.","Reabsorve sódio sem água."],["1d4usxkg5","What is the role of the distal convoluted tubule?","Reabsorbs Na+, Cl- (NCC); impermeable to water; PTH increases Ca2+ reabsorption (Na+/Ca2+ exchange).","Reabsorve sódio e cálcio."],["16geo4oa7","What is the role of the collecting duct principal cells?","Reabsorb Na+ (ENaC) in exchange for K+ secretion (aldosterone), water reabsorption via aquaporin-2 (ADH).","Sódio, potássio e água."],["1144rwlie","What is the role of the alpha-intercalated cells?","Secrete H+ (H+-ATPase, H+/K+-ATPase) and reabsorb HCO3-; increased by aldosterone.","Secretam H+."],["n6la1vs1m","What is the role of the beta-intercalated cells?","Secrete HCO3- and reabsorb H+ (in alkalosis).","Secretam bicarbonato."],["ncij5ir0u","What is the mechanism of Fanconi syndrome?","Generalized PCT reabsorption defect: glucosuria, aminoaciduria, phosphaturia, bicarbonaturia (type 2 RTA), hypokalemia; causes: multiple myeloma, Wilson, cisplatin, tenofovir, expired tetracyclines.","Defeito generalizado do túbulo proximal."],["k13896635","What is Bartter syndrome?","Reabsorption defect in thick ascending loop (NKCC2): hypokalemia, metabolic alkalosis, hypercalciuria; like loop diuretic.","Como diurético de alça."],["1gvip8ub3","What is Gitelman syndrome?","Reabsorption defect of NaCl in DCT: hypokalemia, hypomagnesemia, metabolic alkalosis, hypocalciuria; like thiazide; milder.","Como tiazídico."],["18zrdeb13","What is Liddle syndrome?","Gain of function in ENaC: hypertension, hypokalemia, metabolic alkalosis, low aldosterone; treat with amiloride.","Hipertensão com aldosterona baixa."],["1022s9pt1","What is syndrome of apparent mineralocorticoid excess?","11-beta-HSD2 deficiency (or licorice) allowing cortisol to activate mineralocorticoid receptors: hypertension, hypokalemia, alkalosis, low aldosterone.","Cortisol age como aldosterona."],["1vulb1q1t","What are the actions of the renin-angiotensin-aldosterone system?","Renin converts angiotensinogen to angiotensin I; ACE converts to angiotensin II, which vasoconstricts, releases aldosterone and ADH, increases thirst and PCT Na+ reabsorption, constricts efferent arteriole.","Sistema renina-angiotensina-aldosterona."],["1cyut3j19","What does ACE also degrade?","Bradykinin (ACE inhibitors increase bradykinin: cough, angioedema).","Bradicinina."],["11u5pztwy","What does ANP do?","Released from atria with volume overload: increases GFR (dilates afferent, constricts efferent), decreases renin, promotes natriuresis.","Natriurese."],["1suptn81g","What does aldosterone do?","Increases Na+ reabsorption (ENaC, Na+/K+-ATPase), K+ secretion, and H+ secretion in the collecting duct.","Retém sódio e elimina potássio."],["1ye9ush15","What does ADH do in the kidney?","Binds V2 receptors on principal cells, inserting aquaporin-2 to reabsorb water; increases urea permeability.","Reabsorve água."],["3jgtc7ul0","What does PTH do in the kidney?","Increases Ca2+ reabsorption in DCT, decreases phosphate reabsorption in PCT, increases 1-alpha-hydroxylase (calcitriol).","Retém cálcio e elimina fosfato."],["1tl0n3wk6","What are the causes of potassium shift out of cells (hyperkalemia)?","Digoxin, hyperosmolarity, lysis of cells, acidosis, beta-blockers, high blood sugar (insulin deficiency), succinylcholine (DO LAB SS).","Causas de saída de potássio."],["1nurcv312","What are the causes of potassium shift into cells (hypokalemia)?","Hypo-osmolarity, alkalosis, beta2 agonists, insulin.","Insulina, alcalose e beta-2."],["1k0kc0n4w","What are ECG findings of hypokalemia?","U waves, flattened T waves, arrhythmias.","Ondas U."],["lc8bmw1dk","What are ECG findings of hyperkalemia?","Peaked T waves, wide QRS, sine wave, arrhythmias.","T apiculada."],["1h6abbu1e","What are symptoms of hyponatremia?","Nausea, malaise, stupor, coma, seizures.","Náusea, confusão, convulsões."],["1sbn4te12","What are symptoms of hypernatremia?","Irritability, stupor, coma.","Irritabilidade e coma."],["1kwxzpa6z","What are symptoms of hypocalcemia?","Tetany, seizures, QT prolongation, Trousseau and Chvostek signs.","Tetania e QT longo."],["hx17eu1px","What are symptoms of hypercalcemia?","Stones, bones, groans, thrones, psychiatric overtones.","Cálculos, ossos, dor abdominal, poliúria."],["1h61cps16","What are symptoms of hypomagnesemia?","Tetany, torsades de pointes, hypokalemia (refractory), hypocalcemia.","Tetania e torsades."],["1v66aoo1f","What are symptoms of hypermagnesemia?","Decreased DTRs, lethargy, bradycardia, hypotension, cardiac arrest, hypocalcemia.","Reflexos diminuídos."],["r2qrru1yn","What are symptoms of hypophosphatemia?","Bone loss, osteomalacia, muscle weakness, rhabdomyolysis, hemolysis (refeeding).","Fraqueza e osteomalácia."],["1nrdark66","Why is hypokalemia refractory with hypomagnesemia?","Low Mg2+ increases renal K+ wasting (ROMK disinhibition).","Magnésio baixo perde potássio."],["1htw1le1h","What is the normal arterial pH, PaCO2, and HCO3-?","pH 7.35-7.45, PaCO2 35-45 mmHg, HCO3- 22-28 mEq/L.","Valores normais da gasometria."],["12wdqrj17","What is the anion gap formula and normal value?","Na+ - (Cl- + HCO3-); normal 8-12 mEq/L.","Ânion gap normal 8 a 12."],["b5s1cj1ml","What are causes of anion gap metabolic acidosis?","GOLDMARK: Glycols (ethylene, propylene), Oxoproline (acetaminophen), L-lactate, D-lactate, Methanol, Aspirin, Renal failure, Ketoacidosis.","Mnemônico GOLDMARK."],["rha4pdvkt","What are causes of non-anion gap metabolic acidosis?","HARDASS: Hyperalimentation, Addison disease, RTA, Diarrhea, Acetazolamide, Spironolactone, Saline infusion.","Diarreia, ATR, acetazolamida."],["iazaeb8iq","What is Winter's formula?","Expected PaCO2 in metabolic acidosis = 1.5 x HCO3- + 8 ± 2; if PaCO2 differs, there is a mixed disorder.","Compensação respiratória esperada."],["x0n0x6hje","What are causes of respiratory acidosis?","Hypoventilation: airway obstruction, acute or chronic lung disease, opioids, sedatives, weakening of respiratory muscles.","Hipoventilação."],["srw4ha145","What are causes of respiratory alkalosis?","Hyperventilation: anxiety, hypoxemia (altitude, PE), salicylates (early), pregnancy, sepsis, cirrhosis.","Hiperventilação."],["3uaczq12b","What are causes of metabolic alkalosis?","Vomiting, loop and thiazide diuretics, hyperaldosteronism, antacid use, Bartter, Gitelman, Cushing.","Vômitos e diuréticos."],["1w5cz6611","How is metabolic alkalosis classified by urine chloride?","Low urine Cl- (<20): saline-responsive (vomiting, remote diuretics). High urine Cl-: saline-resistant (hyperaldosteronism, current diuretics, Bartter).","Cloro urinário define a resposta ao soro."],["1adk05b15","What is the renal compensation for respiratory acidosis?","Increased HCO3- reabsorption (takes days).","Retém bicarbonato."],["1qaq2kxqg","What is the expected HCO3- increase in chronic respiratory acidosis?","About 3.5 mEq/L per 10 mmHg PaCO2 increase (acute: 1 per 10).","Aumento de bicarbonato esperado."],["y87fv58zn","What is type 1 (distal) renal tubular acidosis?","Defective alpha-intercalated cell H+ secretion: urine pH >5.5, hypokalemia, calcium phosphate stones; causes: amphotericin B, lithium, autoimmune (Sjögren, SLE), analgesic nephropathy.","Urina alcalina e cálculos."],["jtn3jd5ke","What is type 2 (proximal) renal tubular acidosis?","Defective PCT HCO3- reabsorption: urine pH <5.5 when HCO3- depleted, hypokalemia, rickets; Fanconi syndrome, multiple myeloma, acetazolamide.","Perda proximal de bicarbonato."],["1a0anbmyn","What is type 4 renal tubular acidosis?","Hypoaldosteronism or aldosterone resistance: hyperkalemia, urine pH <5.5, decreased ammoniagenesis; diabetes, ACE inhibitors, ARBs, NSAIDs, spironolactone, trimethoprim.","Hipercalemia por baixa aldosterona."],["12zn40tv6","What are the kidney's endocrine functions?","EPO, calcitriol, renin, prostaglandins (dilate afferent arteriole).","EPO, vitamina D, renina."],["owh5ajz1n","What is the role of prostaglandins in renal hemodynamics?","Dilate afferent arterioles to maintain GFR in low-volume states; inhibited by NSAIDs.","Dilatam a aferente."],["doqjgl16r","What is urine concentration mechanism?","Countercurrent multiplication in loop of Henle creates medullary osmotic gradient; ADH allows water reabsorption in collecting duct.","Multiplicação em contracorrente."],["iy6k8rwrx","What is free water clearance?","Volume of solute-free water excreted; positive in dilute urine (DI), negative in concentrated urine (SIADH).","Depuração de água livre."],["zjd0k515v","What is fractional excretion of sodium (FENa)?","(UNa x PCr) / (PNa x UCr) x 100; <1% suggests prerenal; >2% suggests intrinsic (ATN).","FENa menor que 1% é pré-renal."],["19d15boy3","What is the BUN/creatinine ratio in prerenal azotemia?","Greater than 20.","Maior que 20."],["13kf14c1h","What is the BUN/creatinine ratio in intrinsic renal failure?","Less than 15.","Menor que 15."],["h3bhvd1fo","What is the urine osmolality in prerenal azotemia?","Greater than 500 mOsm/kg.","Acima de 500."],["1d8ipldmp","What is the urine osmolality in ATN?","Less than 350 mOsm/kg (isosthenuric).","Abaixo de 350."],["1k9i03d1i","Why is FENa unreliable with diuretic use?","Diuretics increase sodium excretion; use fractional excretion of urea instead (<35% prerenal).","Usar excreção fracionada de ureia."],["1pdwbgw1k","What happens to renal function in pregnancy?","Increased GFR and RPF (about 50%), decreased BUN and creatinine, mild glucosuria.","Filtração aumenta."],["1o0j8awl7","What happens to renal function with aging?","Decreased GFR, renal mass, concentrating ability; creatinine may stay normal due to less muscle.","Filtração diminui."],["1iqk34y1t","What is the role of ammonium in acid excretion?","NH3 produced from glutamine in the PCT buffers H+ in urine (NH4+); main adaptive response to acidosis.","Amônio elimina ácido."],["1x9g2g116","What is titratable acid?","H+ buffered by phosphate in urine.","Ácido tamponado pelo fosfato."],["ueebj810s","What does a urine anion gap help distinguish?","Non-anion gap acidosis: negative urine anion gap (high NH4+) suggests GI loss (diarrhea); positive suggests RTA.","Diarreia versus acidose tubular."],["o197f1y07","What is the delta-delta (delta gap) used for?","Detects coexisting metabolic disorders in anion gap acidosis: compares change in AG to change in HCO3-.","Detecta distúrbios mistos."],["1ygtpgh7s","What are the effects of acidosis on potassium?","Shifts K+ out of cells (hyperkalemia).","Potássio sai das células."],["pe0s3m49w","What are the effects of alkalosis on calcium?","Increases albumin binding of Ca2+, decreasing ionized Ca2+ (tetany).","Cálcio ionizado cai."],["1y9ahuq1p","What is the most important determinant of ECF volume?","Total body sodium.","Sódio corporal total."],["1tqczeb1f","What is the most important determinant of plasma osmolality?","Water balance (ADH and thirst).","Balanço de água."],["s1g4jqsec","What is hypovolemic hyponatremia's cause and urine sodium?","Renal losses (diuretics, adrenal insufficiency): urine Na >20. Extrarenal (vomiting, diarrhea): urine Na <20.","Sódio urinário define a causa."],["1ls88c186","What is euvolemic hyponatremia's causes?","SIADH, hypothyroidism, adrenal insufficiency (glucocorticoid deficiency), primary polydipsia, beer potomania.","SIADH e polidipsia."],["15ef80ayf","What is hypervolemic hyponatremia's causes?","Heart failure, cirrhosis, nephrotic syndrome, renal failure.","Insuficiência cardíaca e cirrose."],["lhxb9xglf","What is pseudohyponatremia?","Falsely low sodium from hyperlipidemia or hyperproteinemia (lab artifact); normal osmolality.","Falsa hiponatremia."],["1fxpe0c1b","What is the sodium correction in hyperglycemia?","Sodium decreases about 1.6-2.4 mEq/L for every 100 mg/dL glucose above normal (translocational).","Corrigir o sódio pela glicose."],["h7jsro18v","What is the safe rate of sodium correction in chronic hyponatremia?","No more than 8-10 mEq/L in 24 hours.","No máximo 8 a 10 por dia."],["1dgtkwl3s","What is primary polydipsia's urine osmolality?","Very low (<100 mOsm/kg), corrects with water restriction.","Urina muito diluída."],["pxd2gk1oz","What is beer potomania?","Low solute intake with high water (beer) causing hyponatremia due to inability to excrete free water.","Pouco soluto e muita cerveja."],["x42n8c10s","What is the treatment of hyperkalemia emergently?","IV calcium (stabilize membrane), insulin plus glucose, beta2 agonists, bicarbonate (shift), then remove K+ (diuretics, binders, dialysis).","Cálcio, insulina e diálise."],["t6p2hj1hh","What is the treatment of hypercalcemia emergently?","IV normal saline, calcitonin, bisphosphonates.","Soro, calcitonina, bisfosfonato."],["12esit3n3","What is the role of the kidney in calcium homeostasis?","Reabsorbs filtered calcium (mostly PCT and TAL; DCT regulated by PTH) and activates vitamin D.","Reabsorve cálcio e ativa vitamina D."],["h4kbla1rx","What is the effect of loop diuretics on calcium?","Increase urinary calcium excretion (used in hypercalcemia).","Aumentam excreção de cálcio."],["15jmq9xl0","What is the effect of thiazides on calcium?","Decrease urinary calcium excretion (used in calcium stones).","Reduzem excreção de cálcio."],["1ef9w1e8i","What is the renal clearance of a drug highly bound to protein?","Low glomerular filtration (only free drug filtered); may be secreted by tubules.","Só a fração livre é filtrada."],["sunmjp12k","What is the purpose of autoregulation of GFR?","Maintains GFR over MAP 80-180 mmHg via myogenic response and tubuloglomerular feedback.","Mantém a filtração estável."],["c6j2iqpoi","What is tubuloglomerular feedback?","Increased NaCl at the macula densa causes afferent vasoconstriction, decreasing GFR.","Sódio na mácula densa contrai a aferente."],["1qg4lrdi2","What is the effect of sympathetic stimulation on GFR?","Afferent and efferent constriction, decreasing RPF and GFR; increases renin.","Reduz fluxo e filtração."],["rzsjxztos","What is the renal effect of hypovolemia on aldosterone and ADH?","Both increase, retaining sodium and water.","Aumentam aldosterona e ADH."],["1dyzb6m21","What is the role of urea in urine concentration?","Contributes to the medullary osmotic gradient via urea recycling.","Contribui para o gradiente."],["yke7buy6g","What is the effect of a high-protein diet on GFR?","Increases GFR (hyperfiltration).","Aumenta a filtração."],["1s5jx2w1n","What is the role of the kidney in long-term BP control?","Pressure natriuresis and RAAS regulate sodium and volume.","Natriurese pressórica."],["j3gniakdz","What is the role of cystatin C?","Alternative GFR marker less dependent on muscle mass.","Marcador alternativo de filtração."],["1hooddtrz","What is the role of the eGFR equation (CKD-EPI)?","Estimates GFR from creatinine, age, sex (now race-free).","Estima a filtração."],["ibwajl1hq","What is creatinine clearance's limitation in cirrhosis?","Overestimates GFR due to low muscle mass and creatinine production.","Superestima a filtração."],["6yjx4qxt6","What is the normal urine output?","About 0.5-1 mL/kg/h (oliguria <400 mL/day, anuria <100 mL/day).","0,5 a 1 mL/kg/h."],["1mldech1g","What is the minimum obligatory urine output?","About 400-500 mL/day to excrete daily solute load.","Cerca de 400 a 500 mL por dia."],["itnops148","What is the renal response to metabolic acidosis?","Increased H+ secretion, HCO3- reabsorption, and ammoniagenesis.","Excreta mais ácido."],["11v695l1v","What is the respiratory compensation for metabolic alkalosis?","Hypoventilation (PaCO2 rises about 0.7 per 1 mEq/L HCO3- rise).","Hipoventilação."],["122h9z0f0","What are causes of hyperkalemia with low renin and aldosterone?","Type 4 RTA (diabetic nephropathy), NSAIDs, ACE inhibitors.","ATR tipo 4."],["1god1z13x","What is contraction alkalosis?","Volume depletion (diuretics, vomiting) increases angiotensin II and aldosterone, increasing HCO3- reabsorption and H+ secretion.","Alcalose por contração de volume."],["1sra5fl1s","Why does vomiting cause hypokalemia?","Metabolic alkalosis and volume depletion increase aldosterone, increasing renal K+ loss.","Perda renal de potássio."],["kolfvej3s","Why does diarrhea cause non-anion gap acidosis?","Loss of HCO3- in stool.","Perda de bicarbonato nas fezes."],["dxoyohluz","What is the role of carbonic anhydrase in the PCT?","Converts H2CO3 to CO2 and water, enabling HCO3- reabsorption; inhibited by acetazolamide.","Permite reabsorção de bicarbonato."],["y4i3by1ow","What is the effect of acetazolamide on urine pH?","Alkaline urine (HCO3- excretion) and hyperchloremic metabolic acidosis.","Urina alcalina e acidose."],["ux4ccjotj","What are the causes of nephrogenic diabetes insipidus?","Lithium, demeclocycline, hypercalcemia, hypokalemia, V2 receptor or aquaporin mutations.","Lítio e hipercalcemia."],["1exxxaj1h","What is the role of the kidney in drug metabolism?","Excretes water-soluble drugs and metabolites; dose adjust in CKD.","Elimina drogas hidrossolúveis."],["1sq9i9vve","What is the renal handling of uric acid?","Filtered, reabsorbed and secreted in the PCT (URAT1); increased by thiazides and loop diuretics, decreased by probenecid.","Ácido úrico no túbulo proximal."],["1llldrh12","What is the cause of hypouricemia with Fanconi syndrome?","Impaired PCT reabsorption of uric acid.","Perda proximal de ácido úrico."],["13ss0wan4","What is the definition of polyuria?","Urine output >3 L/day.","Mais de 3 litros por dia."],["f5ubky1rw","What are the causes of osmotic diuresis?","Hyperglycemia, mannitol, high urea (post-obstructive, high protein feeding).","Glicose e manitol."],["ckzwq41j4","What does a urine specific gravity of 1.010 suggest?","Isosthenuria (urine osmolality equal to plasma), seen in ATN or CKD.","Urina isostenúrica."],["1jk6aeyfz","What are the renal effects of angiotensin II receptor blockade in bilateral renal artery stenosis?","Acute decrease in GFR (efferent dilation removes compensation).","Queda da filtração."],["gks9ny1d9","What are the effects of NSAIDs combined with ACE inhibitors and diuretics?","Triple whammy: high risk of acute kidney injury.","Risco de lesão renal aguda."],["152frzw8o","What is the role of the kidney in phosphate regulation?","PCT reabsorption via NaPi2a, inhibited by PTH and FGF23.","Reabsorção de fosfato regulada."],["dho10j1wc","What is the role of FGF23 in CKD?","Increases early to maintain phosphate excretion; decreases calcitriol.","Aumenta na doença renal."],["1tq22pbmu","What is the definition of azotemia?","Elevated BUN and creatinine.","Ureia e creatinina elevadas."],["9unj8o16z","What is the definition of uremia?","Clinical syndrome of advanced renal failure: nausea, anorexia, pericarditis, asterixis, encephalopathy, platelet dysfunction.","Síndrome urêmica."],["nsam98ky0","What are the indications for urgent dialysis?","AEIOU: Acidosis, Electrolyte abnormalities (hyperkalemia), Ingestion (toxins), Overload (fluid), Uremic symptoms (pericarditis, encephalopathy).","Indicações de diálise AEIOU."],["rao2gfa8a","Which toxins are dialyzable?","Salicylates, lithium, methanol, ethylene glycol, theophylline, valproate (high dose), metformin (I STUMBLED).","Salicilato, lítio, metanol."]]},{"name":"Anatomy","cards":[["1nabkhz19","Which kidney is lower and why?","Right kidney, displaced by the liver.","O direito, por causa do fígado."],["vjh18s1k2","Which kidney is preferred for living donor transplant and why?","Left kidney: longer renal vein.","O esquerdo; veia renal mais longa."],["gqrbc31or","What is the order of structures in the renal hilum from anterior to posterior?","Renal vein, renal artery, ureter (VAU: Venous, Arterial, Ureter).","Veia, artéria, ureter."],["cljoaho4z","What is the course of the ureter relative to vessels?","Passes under the uterine artery and under the vas deferens (water under the bridge).","Passa sob a artéria uterina e o ducto deferente."],["1xk2m11d7","Why are ureters at risk during hysterectomy?","Proximity to the uterine artery (ligation can injure the ureter).","Proximidade com a artéria uterina."],["1a8od6bmi","Where are the narrowest points of the ureter (stone impaction sites)?","Ureteropelvic junction, pelvic inlet (crossing iliac vessels), ureterovesical junction.","Junção pieloureteral, vasos ilíacos, junção vesical."],["1lv91lc1u","What is the blood flow path through the kidney?","Renal artery, segmental, interlobar, arcuate, interlobular (cortical radiate), afferent arteriole, glomerulus, efferent arteriole, vasa recta/peritubular capillaries, venous return.","Caminho do sangue no rim."],["13fxaf611","What is the glomerular filtration barrier?","Fenestrated capillary endothelium, fused basement membrane (heparan sulfate, negative charge), podocyte foot processes (slit diaphragm, nephrin).","Endotélio, membrana basal e podócitos."],["6ds8jf1dj","What does loss of the negative charge barrier cause?","Albuminuria (minimal change disease).","Perda de albumina."],["56ph2sghd","What is the juxtaglomerular apparatus?","Mesangial cells, JG cells (modified smooth muscle of afferent arteriole secreting renin), macula densa (NaCl sensor in DCT).","Aparelho justaglomerular."],["1uan1xoaz","What triggers renin release?","Decreased renal perfusion pressure, decreased NaCl at macula densa, beta1 sympathetic stimulation.","Hipoperfusão, pouco sódio, simpático."],["wxpswv3q8","What are the segments of the nephron?","Glomerulus, proximal convoluted tubule, loop of Henle (thin descending, thin ascending, thick ascending), distal convoluted tubule, collecting duct.","Segmentos do néfron."],["12wnsztqq","Which part of the nephron is most vulnerable to ischemia?","Proximal straight tubule and thick ascending limb (medulla).","Túbulo proximal reto e alça ascendente espessa."],["11ldnprg4","Which part of the nephron is most vulnerable to toxins?","Proximal convoluted tubule.","Túbulo contorcido proximal."],["14122t119","What is the renal cortex vs medulla composition?","Cortex: glomeruli, convoluted tubules. Medulla: loops of Henle, collecting ducts (pyramids).","Córtex e medula."],["11iwzdsy0","What are the renal papillae vulnerable to?","Papillary necrosis (diabetes, sickle cell, NSAIDs, pyelonephritis, urinary obstruction).","Necrose de papila."],["ff9noz1fx","What is the role of the vasa recta?","Countercurrent exchange preserving medullary osmotic gradient.","Preserva o gradiente medular."],["5zvu03mrh","What is the embryologic origin of the bladder trigone?","Mesonephric ducts.","Ductos mesonéfricos."],["yoqg26111","What is the innervation of the bladder?","Parasympathetic (S2-S4, pelvic splanchnic) contracts detrusor; sympathetic (T10-L2, hypogastric) relaxes detrusor and contracts internal sphincter; pudendal (somatic) external sphincter.","Inervação da bexiga."],["1roytvq1g","What is the anatomical location of the kidneys?","Retroperitoneal, T12-L3; left higher than right.","Retroperitoneais entre T12 e L3."],["1o5hr4r1i","What layers surround the kidney?","Renal capsule, perirenal fat, renal (Gerota) fascia, pararenal fat.","Cápsula, gordura e fáscia de Gerota."],["1opwlxg1y","What does the left renal vein receive?","Left gonadal vein, left adrenal vein, left inferior phrenic vein.","Gonadal e adrenal esquerdas."],["1wkj2fj7y","What is a horseshoe kidney's anatomic relationship?","Fused lower poles trapped under the inferior mesenteric artery.","Preso sob a mesentérica inferior."],["5yrgp2osh","What is the arcuate artery's location?","At the corticomedullary junction.","Na junção corticomedular."],["siytfo1w7","What is the bladder's normal capacity in adults?","About 400-600 mL.","Cerca de 400 a 600 mL."],["16it3j3qz","What is the male urethra's segments?","Prostatic, membranous (most commonly injured in pelvic fracture), spongy (penile; injured in straddle injury).","Prostática, membranosa e esponjosa."],["6ic5vl1j9","What is the posterior urethral injury mechanism?","Pelvic fracture tears membranous urethra: high-riding prostate, blood at meatus, inability to void.","Fratura pélvica."],["j5694yzfj","What is the anterior urethral injury mechanism?","Straddle injury: bulbar urethra; urine leaks into scrotum and perineum.","Queda a cavaleiro."],["x0jaukphi","What should be done before Foley catheterization with blood at the urethral meatus?","Retrograde urethrogram.","Uretrografia retrógrada."],["an20ry1lk","What is the renal blood flow percentage of cardiac output?","About 20-25%.","Cerca de 20 a 25%."],["uejv9j1p1","What is the anatomic basis of right-sided varicocele concern?","Right gonadal vein drains into IVC; isolated right varicocele suggests IVC obstruction or mass.","Varicocele direita sugere massa."],["1cnf99x1t","What is the pelvic floor's role in continence?","Levator ani supports bladder neck; weakness causes stress incontinence.","Sustenta o colo vesical."],["rmope31cc","Which nerve is responsible for voluntary control of urination?","Pudendal nerve (external urethral sphincter).","Nervo pudendo."],["1yo3r3aqz","What is the anatomic location of the macula densa?","Distal convoluted tubule where it contacts the afferent arteriole of its own glomerulus.","Túbulo distal junto à arteríola aferente."],["1872802qc","What are the cells of the collecting duct?","Principal cells (Na+ reabsorption, K+ secretion, ADH water channels) and intercalated cells (alpha secrete H+, beta secrete HCO3-).","Células principais e intercalares."],["mk4lgt7fj","What is the brush border of the PCT for?","Increases surface area for reabsorption.","Aumenta a área de reabsorção."],["1lldl3qa2","Where is erythropoietin produced in the kidney?","Interstitial fibroblast-like cells of the peritubular cortex.","Células intersticiais do córtex."],["1ekq28esh","Where is 1-alpha-hydroxylase located?","Proximal convoluted tubule.","Túbulo proximal."],["10qykkive","What is the anatomic site of urea recycling?","Inner medullary collecting duct (via ADH-sensitive urea transporters).","Ducto coletor medular interno."],["4dxl35jux","What is the anatomical vulnerability of the renal medulla to hypoxia?","Low blood flow and high metabolic activity of the thick ascending limb.","Pouco fluxo e muito gasto energético."]]},{"name":"Pathology","cards":[["1j9879tm2","What are RBC casts associated with?","Glomerulonephritis, hypertensive emergency.","Glomerulonefrite."],["1qofcfojk","What are WBC casts associated with?","Tubulointerstitial inflammation, acute pyelonephritis, transplant rejection.","Pielonefrite e nefrite intersticial."],["126hbosaz","What are fatty casts (oval fat bodies) associated with?","Nephrotic syndrome (Maltese cross under polarized light).","Síndrome nefrótica."],["1m0dflg99","What are granular (muddy brown) casts associated with?","Acute tubular necrosis.","Necrose tubular aguda."],["y84itx1ax","What are waxy casts associated with?","End-stage renal disease and chronic kidney disease.","Doença renal crônica."],["9jmnlotld","What are hyaline casts associated with?","Nonspecific; concentrated urine, after exercise or dehydration.","Inespecíficos."],["5opu6h1ms","What is nephritic syndrome?","Glomerular inflammation: hematuria with RBC casts, azotemia, oliguria, hypertension, proteinuria <3.5 g/day.","Hematúria, hipertensão e proteinúria leve."],["1rutglr1j","What is nephrotic syndrome?","Massive proteinuria (>3.5 g/day), hypoalbuminemia, edema, hyperlipidemia, fatty casts; hypercoagulability (antithrombin loss), infection risk.","Proteinúria maciça e edema."],["1fznpbg1q","Why is nephrotic syndrome hypercoagulable?","Urinary loss of antithrombin III and increased hepatic clotting factor production.","Perda de antitrombina."],["mmv6gabpy","What is the most common nephrotic syndrome in children?","Minimal change disease.","Doença de lesão mínima."],["3u47c11qg","What are features of minimal change disease?","Normal glomeruli on light microscopy, effacement of podocyte foot processes on EM, selective albuminuria; responds to steroids; may follow infection, vaccine, Hodgkin lymphoma.","Microscopia óptica normal; responde a corticoide."],["ewqw4m1bw","What is focal segmental glomerulosclerosis?","Most common nephrotic syndrome in Black and Hispanic adults: segmental sclerosis and hyalinosis; associated with HIV, heroin, obesity, sickle cell, APOL1; poor steroid response.","Esclerose segmentar; HIV e obesidade."],["933lps1xf","What is the collapsing variant of FSGS associated with?","HIV-associated nephropathy.","Nefropatia do HIV."],["t31zab1xp","What is membranous nephropathy?","Most common nephrotic syndrome in White adults: diffuse capillary and GBM thickening, spike and dome on EM, granular IF; anti-PLA2R antibodies; secondary to SLE, HBV, HCV, drugs (NSAIDs, penicillamine), solid tumors.","Espículas na membrana; anti-PLA2R."],["1dj6f4p1e","What is the complication of membranous nephropathy?","Renal vein thrombosis (hypercoagulability).","Trombose da veia renal."],["1ge5keq11","What is amyloidosis's renal finding?","Nephrotic syndrome with Congo red apple-green birefringence; AL (myeloma) or AA (chronic inflammation).","Birrefringência verde-maçã."],["17xner1mb","What is diabetic glomerulonephropathy?","Most common cause of ESRD in US: GBM thickening, mesangial expansion, Kimmelstiel-Wilson nodules (nodular glomerulosclerosis), efferent arteriole hyalinosis.","Nódulos de Kimmelstiel-Wilson."],["8b1sjggb1","What is the first sign of diabetic nephropathy?","Microalbuminuria (moderately increased albuminuria).","Microalbuminúria."],["1ex10hw69","What is the treatment to slow diabetic nephropathy?","ACE inhibitors or ARBs, SGLT2 inhibitors, finerenone, glycemic and BP control.","IECA e glifozinas."],["14grb3b8k","What is membranoproliferative glomerulonephritis?","Nephritic or nephrotic: tram-track GBM splitting; type I (HBV, HCV, subendothelial deposits), type II (dense deposit disease, C3 nephritic factor).","Duplo contorno; hepatites."],["xp2tds182","What is acute poststreptococcal glomerulonephritis?","Nephritic syndrome 2-4 weeks after group A strep pharyngitis or skin infection: cola-colored urine, periorbital edema, hypertension; low C3, positive ASO; subepithelial humps.","Após faringite ou impetigo; C3 baixo."],["on768o1hg","What is the prognosis of PSGN in children vs adults?","Children usually recover; adults may progress to renal insufficiency.","Criança se recupera."],["13nn92w3i","What is rapidly progressive glomerulonephritis?","Crescent formation (fibrin and macrophages) with rapid loss of renal function over weeks; types I (anti-GBM), II (immune complex), III (pauci-immune ANCA).","Crescentes; perda rápida da função."],["1qw70y01r","What is Goodpasture syndrome?","Anti-GBM antibodies against type IV collagen (alpha-3): hematuria and hemoptysis; linear IF; type II hypersensitivity; treat with plasmapheresis.","Anti-membrana basal; hemoptise e hematúria."],["yjtmc71w7","What is IgA nephropathy (Berger disease)?","Most common glomerulonephritis worldwide: episodic gross hematuria days after URI or GI infection; mesangial IgA deposits.","Hematúria dias após infecção."],["uckpubsxl","How does IgA nephropathy differ from PSGN in timing?","IgA nephropathy occurs concurrently or within days of infection; PSGN after 2-4 weeks.","IgA logo; PSGN semanas depois."],["9jrbfgf2b","What is diffuse proliferative glomerulonephritis?","Most common cause of death in SLE: wire looping of capillaries, subendothelial deposits, granular IF; low complement.","Nefrite lúpica com alças de arame."],["1oui0t920","What is Alport syndrome's renal presentation?","Hematuria, progressive renal failure; GBM splitting (basket-weave) on EM; sensorineural deafness, lens abnormalities; COL4A5 X-linked.","Hematúria, surdez e alterações oculares."],["m0jeyt175","What is thin basement membrane disease?","Benign familial hematuria with thin GBM (autosomal dominant).","Hematúria benigna familiar."],["8rl0zhkwg","What are pauci-immune glomerulonephritides?","GPA (c-ANCA), microscopic polyangiitis and EGPA (p-ANCA): RPGN with minimal immune deposits.","Vasculites ANCA."],["sp4kbvttg","What is acute kidney injury?","Abrupt decline in renal function: increase in creatinine ≥0.3 mg/dL in 48 hours or ≥1.5x baseline, or oliguria.","Lesão renal aguda."],["m090jn3gq","What are the categories of AKI?","Prerenal (decreased perfusion), intrinsic (ATN, AIN, glomerulonephritis), postrenal (obstruction).","Pré-renal, renal, pós-renal."],["x9i5qg1sl","What are lab findings in prerenal AKI?","BUN/Cr >20, FENa <1%, urine osmolality >500, urine Na <20.","Ureia/creatinina >20; FENa <1%."],["244zdq1v9","What are lab findings in intrinsic AKI (ATN)?","BUN/Cr <15, FENa >2%, urine osmolality <350, urine Na >40, muddy brown casts.","FENa >2%; cilindros granulosos."],["1hxeiuv4i","What are lab findings in postrenal AKI?","Varies; hydronephrosis on ultrasound; BUN/Cr may be >15 early.","Hidronefrose."],["tgjo4x1p9","What causes acute tubular necrosis?","Ischemia (hypotension, shock) or nephrotoxins (aminoglycosides, contrast, cisplatin, myoglobin, heavy metals, ethylene glycol).","Isquemia e nefrotoxinas."],["1t5obwx1f","What are the phases of ATN?","Inciting event, maintenance phase (oliguria, hyperkalemia, acidosis, uremia), recovery phase (polyuria, hypokalemia).","Fases da necrose tubular."],["5pltow10r","What is acute interstitial nephritis?","Interstitial inflammation, often drug-induced (penicillins, NSAIDs, PPIs, rifampin, diuretics, sulfonamides): fever, rash, eosinophilia, WBC casts, urine eosinophils.","Febre, rash e eosinofilia por drogas."],["148iasgyo","What is renal papillary necrosis?","Sloughing of necrotic papillae (gross hematuria, flank pain): sickle cell, acute pyelonephritis, analgesics (NSAIDs), diabetes.","Necrose de papila."],["jpqjor131","What is contrast-induced nephropathy?","AKI after IV contrast; risk factors CKD, diabetes, dehydration; prevent with hydration.","Lesão por contraste."],["hruy05rpl","What is rhabdomyolysis-induced AKI?","Myoglobin causes tubular toxicity: dark urine with positive heme dipstick but no RBCs; hyperkalemia, hyperphosphatemia, hypocalcemia.","Mioglobina lesa os túbulos."],["1fpbrt9gz","What is ethylene glycol's renal effect?","Calcium oxalate crystals (envelope-shaped) and ATN; anion gap acidosis.","Cristais de oxalato."],["1gz699h8j","What is tumor lysis syndrome's renal effect?","Uric acid nephropathy causing AKI.","Nefropatia por ácido úrico."],["lv9k7g1pj","What is hepatorenal syndrome?","Prerenal-like AKI in advanced cirrhosis from splanchnic vasodilation and renal vasoconstriction.","Lesão renal na cirrose."],["1nfp3e61j","What is chronic kidney disease's most common causes?","Diabetes mellitus and hypertension.","Diabetes e hipertensão."],["12533xp1n","What are consequences of CKD?","Anemia (low EPO), renal osteodystrophy, hyperkalemia, metabolic acidosis, hypertension, uremia, fluid overload, hyperphosphatemia, hypocalcemia, secondary hyperparathyroidism.","Anemia, osteodistrofia, acidose."],["ahqzhc14j","What is the leading cause of death in CKD?","Cardiovascular disease.","Doença cardiovascular."],["vdlajp116","What is acute pyelonephritis?","Neutrophilic infiltration of renal interstitium: fever, flank pain, CVA tenderness, WBC casts; ascending infection (E. coli).","Febre, dor lombar e cilindros leucocitários."],["1ic9jrlq1","What is chronic pyelonephritis?","Recurrent infections with corticomedullary scarring, blunted calyces, thyroidization of kidney (eosinophilic casts); vesicoureteral reflux.","Cicatrizes e tireoidização."],["9jv6fu1sf","What is xanthogranulomatous pyelonephritis?","Rare chronic pyelonephritis with granulomatous tissue containing foamy macrophages; associated with Proteus and staghorn stones.","Forma crônica com cálculo coraliforme."],["1jlpqx91f","What is emphysematous pyelonephritis?","Gas-forming infection of kidney in diabetics; surgical emergency.","Infecção com gás em diabéticos."],["16h1xo31d","What is vesicoureteral reflux?","Retrograde urine flow from bladder to ureter, predisposing children to UTIs and renal scarring; diagnosed with voiding cystourethrogram.","Refluxo vesicoureteral."],["1v7inix1s","What are the types of kidney stones?","Calcium oxalate (most common), calcium phosphate, struvite, uric acid, cystine.","Tipos de cálculos."],["tntzke1ll","What are features of calcium oxalate stones?","Radiopaque, envelope or dumbbell crystals; hypercalciuria, low citrate, ethylene glycol, vitamin C abuse, Crohn disease (fat malabsorption).","Mais comum; envelope."],["1gwoh60qz","What are features of calcium phosphate stones?","Radiopaque, wedge-shaped prisms; high urine pH; type 1 RTA, hyperparathyroidism.","pH urinário alto."],["ohvcwm6rp","What are features of struvite stones?","Ammonium magnesium phosphate, radiopaque, coffin-lid crystals; urease-positive infections (Proteus, Klebsiella); staghorn calculi.","Infecção por Proteus; coraliforme."],["1y7t6jecn","What are features of uric acid stones?","Radiolucent, rhomboid or rosette crystals; low urine pH; gout, hyperuricemia, tumor lysis; treat with urine alkalinization, allopurinol.","Radiotransparente; pH ácido."],["1njnv2fg1","What are features of cystine stones?","Hexagonal crystals, faintly radiopaque, cystinuria (COLA transporter defect); positive sodium nitroprusside test.","Cristais hexagonais."],["1t0j37e56","What is the presentation of nephrolithiasis?","Colicky flank pain radiating to groin, hematuria, nausea; noncontrast CT is diagnostic.","Cólica renal irradiando para a virilha."],["2gc0sw1j7","What is the prevention of calcium stones?","Increased fluids, thiazides (reduce calcium excretion), citrate, low sodium diet; normal dietary calcium.","Líquidos, tiazídico e citrato."],["1rretphhb","What is hydronephrosis?","Distension of renal pelvis and calyces from urinary obstruction (stones, BPH, cancer, pregnancy, posterior urethral valves).","Dilatação por obstrução."],["i4b44vk0r","What is renal cell carcinoma?","Most common primary renal malignancy: clear cell from PCT; hematuria, palpable mass, flank pain (classic triad, rare); polycythemia (EPO), hypercalcemia (PTHrP); smoking, obesity, VHL.","Carcinoma renal de células claras."],["2qlbjxmwf","What chromosome is deleted in clear cell RCC?","3p (VHL gene).","Cromossomo 3p."],["1w1cg4jlw","How does renal cell carcinoma spread?","Hematogenous (lung, bone); invades renal vein and IVC (left varicocele).","Disseminação hematogênica."],["g3mj7h1fk","What paraneoplastic syndromes occur in RCC?","Polycythemia (EPO), hypercalcemia (PTHrP), hypertension (renin), Cushing (ACTH), Stauffer syndrome (liver dysfunction).","Policitemia e hipercalcemia."],["1vu35um1q","What is renal oncocytoma?","Benign tumor of collecting duct intercalated cells; mahogany brown with central scar; large eosinophilic cells with mitochondria.","Tumor benigno com cicatriz central."],["go6xah6rj","What is angiomyolipoma?","Benign tumor of blood vessels, smooth muscle, and fat; associated with tuberous sclerosis.","Tumor benigno; esclerose tuberosa."],["15zwtw31s","What is Wilms tumor (nephroblastoma)?","Most common renal malignancy in children 2-4: large palpable unilateral flank mass, hematuria, hypertension; WT1 or WT2 mutations; triphasic histology.","Massa abdominal em criança pequena."],["1pwpjgv1c","What syndromes are associated with Wilms tumor?","WAGR, Denys-Drash, Beckwith-Wiedemann.","WAGR, Denys-Drash, Beckwith-Wiedemann."],["fsy7nw1lq","What is urothelial carcinoma of the bladder?","Most common bladder tumor: painless hematuria; risk factors smoking, aromatic amines, cyclophosphamide, phenacetin.","Hematúria indolor em fumante."],["198rsr71c","What is squamous cell carcinoma of the bladder associated with?","Chronic irritation: Schistosoma haematobium, chronic cystitis, long-term catheters.","Esquistossomose."],["1ftneuz8l","What is adenocarcinoma of the bladder associated with?","Urachal remnants, cystitis glandularis, bladder exstrophy.","Resto do úraco."],["ejsv5y17v","What is ADPKD's renal presentation?","Bilateral enlarged multicystic kidneys, flank pain, hematuria, hypertension, progressive renal failure.","Rins policísticos bilaterais."],["u6gk5hzkk","What is the treatment that slows ADPKD progression?","Tolvaptan (V2 antagonist) and BP control.","Tolvaptana."],["1in237o4e","What is ARPKD's presentation?","Infantile presentation with enlarged kidneys, Potter sequence, congenital hepatic fibrosis.","Lactente com fibrose hepática."],["apl0p91oe","What is medullary sponge kidney?","Collecting duct dilation in medullary pyramids: nephrocalcinosis, stones, UTIs; usually benign.","Ductos coletores dilatados."],["xv3ab11gr","What is simple renal cyst?","Common benign fluid-filled cyst with thin smooth walls; no follow-up needed.","Cisto simples benigno."],["17lffnh1y","What is renal artery stenosis?","Atherosclerosis (older men) or fibromuscular dysplasia (young women): renovascular hypertension, renal bruit, AKI with ACE inhibitors.","Aterosclerose ou displasia fibromuscular."],["1vec39t1g","What is renal infarction's presentation?","Flank pain, hematuria, elevated LDH; emboli from AF.","Dor lombar e LDH alto."],["4t1y4a15g","What is the 'string of beads' appearance on angiography?","Fibromuscular dysplasia.","Displasia fibromuscular."],["i9pbh11ve","What is diffuse cortical necrosis?","Acute generalized cortical infarction of both kidneys (DIC, obstetric catastrophes like abruption).","Necrose cortical bilateral."],["10hv47ahx","What is the most common cause of nephrotic syndrome in HIV?","Collapsing FSGS.","GESF colapsante."],["xa4cb1vfp","What glomerular disease is associated with hepatitis B?","Membranous nephropathy (and MPGN, PAN).","Nefropatia membranosa."],["xa4cdovfp","What glomerular disease is associated with hepatitis C?","MPGN type I and cryoglobulinemia.","GNMP e crioglobulinemia."],["wecbjfvt9","What glomerular disease is associated with Hodgkin lymphoma?","Minimal change disease.","Lesão mínima."],["5rvofzfbo","What glomerular disease is associated with solid tumors?","Membranous nephropathy.","Nefropatia membranosa."],["1wszhqs1l","What glomerular disease is associated with heroin use?","FSGS.","GESF."],["17p0soy69","What glomerular disease is associated with NSAIDs?","Minimal change disease and membranous nephropathy (also AIN).","Lesão mínima e membranosa."],["1g5fxoubg","What glomerular disease is associated with multiple myeloma?","AL amyloidosis, light chain cast nephropathy.","Amiloidose e rim do mieloma."],["bdobly1j7","What is light chain cast nephropathy?","Bence Jones proteins form casts in distal tubules, causing AKI.","Cilindros de cadeias leves."],["1ie3x5d1f","What glomerular disease features low complement?","PSGN, SLE nephritis, MPGN, cryoglobulinemia.","PSGN, lúpus e GNMP."],["1yoy9o61o","What glomerular disease features normal complement?","IgA nephropathy, anti-GBM, pauci-immune GN, minimal change, FSGS, membranous.","Complemento normal."],["8pl62o1lt","What is the immunofluorescence pattern in anti-GBM disease?","Linear.","Linear."],["1ywk2tcw2","What is the immunofluorescence pattern in PSGN and SLE?","Granular (lumpy-bumpy).","Granular."],["w0nqpy6rm","What is the immunofluorescence pattern in pauci-immune GN?","Negative or minimal.","Negativa."],["3ioulb14x","What is the electron microscopy finding in PSGN?","Subepithelial immune complex humps.","Corcovas subepiteliais."],["871hp8j0u","What is the electron microscopy finding in membranous nephropathy?","Subepithelial deposits with spike and dome appearance.","Espículas e cúpulas."],["8ayt001gz","What is the electron microscopy finding in MPGN type I?","Subendothelial deposits with tram-track appearance.","Duplo contorno."],["1e9vyk0do","What is the electron microscopy finding in dense deposit disease?","Intramembranous dense deposits (MPGN type II).","Depósitos densos intramembranosos."],["ua4o53q0e","What is the treatment of minimal change disease?","Corticosteroids.","Corticoide."],["jtk1uk9fu","What is the treatment of Goodpasture syndrome?","Plasmapheresis, corticosteroids, cyclophosphamide.","Plasmaférese e imunossupressão."],["ocrif9i3m","What is the treatment of ANCA-associated RPGN?","Corticosteroids plus rituximab or cyclophosphamide.","Corticoide com rituximabe."],["pyfaaeoyb","What causes hematuria with dysmorphic RBCs?","Glomerular disease.","Doença glomerular."],["1vrrdgoiz","What causes painless gross hematuria in an older smoker?","Bladder cancer until proven otherwise (cystoscopy).","Câncer de bexiga."],["flf2vbf94","What is the workup of microscopic hematuria in adults?","Urinalysis repeat, imaging (CT urography), cystoscopy depending on risk.","Imagem e cistoscopia."],["192ji56gr","What causes transient proteinuria?","Fever, exercise, orthostatic proteinuria (adolescents).","Febre, exercício e ortostatismo."],["jzkspbls4","What is the treatment of hyperkalemia in CKD chronically?","Low potassium diet, potassium binders (patiromer, sodium zirconium cyclosilicate), loop diuretics.","Dieta e quelantes de potássio."],["1v82w8qzd","What is the treatment of anemia in CKD?","Iron supplementation and erythropoiesis-stimulating agents.","Ferro e eritropoetina."],["4u78uiuun","What is the treatment of hyperphosphatemia in CKD?","Dietary phosphate restriction and phosphate binders (sevelamer, calcium acetate, lanthanum).","Quelantes de fósforo."],["1hk0h9c1m","What is calciphylaxis?","Vascular calcification and skin necrosis in ESRD patients (calcific uremic arteriolopathy).","Calcificação vascular com necrose."],["vwf0vu1bi","Which benign renal tumors are most common in adults?","Angiomyolipoma and oncocytoma.","Angiomiolipoma e oncocitoma."],["ubr3e213t","What is the Bosniak classification used for?","Risk stratification of renal cysts for malignancy on CT.","Classifica cistos renais."],["18hpir55y","What is the most common cause of AKI in hospitalized patients?","Acute tubular necrosis (ischemic or toxic) and prerenal azotemia.","Necrose tubular aguda."],["1mzqjcneo","What is the role of ultrasound in AKI?","Rule out obstruction (hydronephrosis) and assess kidney size (small in CKD).","Excluir obstrução."],["dpxivixvm","What are urine eosinophils associated with?","Acute interstitial nephritis (also atheroembolic disease); low sensitivity.","Nefrite intersticial."],["1ihgql019","What is atheroembolic renal disease?","Cholesterol emboli after vascular procedures: AKI, livedo reticularis, eosinophilia, low complement.","Embolia de colesterol após cateterismo."],["j6fcui154","What is the most common glomerular disease causing ESRD after diabetes?","Hypertensive nephrosclerosis and glomerulonephritis.","Nefroesclerose hipertensiva."],["b2lu9f1vw","What is the renal biopsy indication in nephrotic syndrome in adults?","Most adults require biopsy (unlike children with presumed minimal change disease).","Adultos geralmente fazem biópsia."],["ftwsbeun5","What is cast nephropathy's urine dipstick finding?","Dipstick negative or weak for protein despite heavy light chain proteinuria (detects albumin only).","Fita não detecta cadeias leves."],["127tyvyh5","What is the urine protein electrophoresis used for?","Detecting monoclonal light chains (Bence Jones) in myeloma.","Detecta cadeias leves."],["ukdb0jh3q","What is the definition of CKD?","Abnormal kidney structure or function (GFR <60 or albuminuria) for >3 months.","Mais de 3 meses."],["1neaog7np","What is uremic pericarditis treated with?","Dialysis.","Diálise."],["1eah2i9wv","What is the cause of bleeding in uremia?","Platelet dysfunction; treat with desmopressin or dialysis.","Disfunção plaquetária."],["4haem61so","What is the renal effect of sickle cell trait?","Isosthenuria, hematuria, papillary necrosis, renal medullary carcinoma.","Urina não concentra."],["1laxcca16","What is renal medullary carcinoma?","Aggressive tumor in young patients with sickle cell trait.","Tumor agressivo no traço falciforme."],["1lr5gs111","What is the cause of BPH-related obstruction?","Hyperplasia of periurethral (transitional zone) prostate causing urinary retention, hydronephrosis.","Hiperplasia da zona de transição."],["s4dl6evdu","What causes urinary retention in a postoperative patient?","Anesthesia, opioids, anticholinergics, pain.","Anestesia e opioides."],["uzaczwmbq","What are the types of urinary incontinence?","Stress (increased abdominal pressure, sphincter weakness), urge (detrusor overactivity), overflow (incomplete emptying), functional.","Esforço, urgência, transbordamento."],["14h054s1s","Treatment of stress incontinence?","Pelvic floor exercises (Kegel), pessaries, surgery (midurethral sling).","Exercícios de Kegel."],["sh3j559cf","Treatment of urge incontinence?","Behavioral (bladder training), antimuscarinics, mirabegron.","Antimuscarínicos."],["1d6b6z41w","Treatment of overflow incontinence?","Catheterization, treat obstruction, bethanechol.","Cateterismo."],["pauscqbxb","What is interstitial cystitis?","Chronic bladder pain with urgency and frequency without infection; diagnosis of exclusion.","Dor vesical crônica sem infecção."],["1s8bre8xa","What is hemorrhagic cystitis's common causes?","Cyclophosphamide, adenovirus, BK virus, radiation.","Ciclofosfamida e adenovírus."],["k02erm1p6","What causes hypertension in children most commonly (secondary)?","Renal parenchymal disease and coarctation of the aorta.","Doença renal e coarctação."],["9e3doaz1t","What is posterior urethral valve's presentation?","Male infant with weak urinary stream, bilateral hydronephrosis, distended bladder, oligohydramnios in utero.","Menino com jato fraco e hidronefrose."],["13f4f284y","What is the most common cause of hydronephrosis in pregnancy?","Physiologic compression of ureters by uterus and progesterone-mediated dilation (right more than left).","Compressão fisiológica."],["1s6mwehty","What is analgesic nephropathy?","Chronic interstitial nephritis and papillary necrosis from long-term NSAID or phenacetin use.","Nefropatia por analgésicos."],["uoqe58100","What is lead nephropathy?","Chronic interstitial nephritis, Fanconi syndrome, gout (saturnine gout).","Nefrite crônica e gota."],["cegdoh1bs","What is lithium nephrotoxicity?","Nephrogenic diabetes insipidus and chronic interstitial nephritis.","Diabetes insípido nefrogênico."],["oraockxx7","What is the presentation of renal vein thrombosis?","Flank pain, hematuria, AKI; associated with membranous nephropathy and hypercoagulable states.","Dor lombar e hematúria."],["8rdvkz1se","What is the role of urine microscopy in AKI?","Casts and crystals differentiate causes (ATN, AIN, GN).","Diferencia as causas."],["12jfanej6","What is obstructive uropathy's reversible component?","Relief of obstruction often restores function if early.","Desobstruir cedo recupera."],["jiz2xp1x7","What is post-obstructive diuresis?","Large-volume urine output after relief of obstruction; monitor electrolytes.","Diurese após desobstrução."],["3vm95gdqb","What is the most common cause of UTI-related bacteremia in elderly men?","E. coli from prostatic or urinary obstruction.","E. coli."],["hlvs3a1hi","What is acute prostatitis's presentation?","Fever, dysuria, perineal pain, tender boggy prostate; avoid vigorous prostate massage.","Próstata dolorosa e amolecida."],["l56ih71bb","What is the cause of gross hematuria after strenuous exercise?","Rhabdomyolysis (myoglobinuria) or exercise-induced hematuria.","Rabdomiólise."],["12lxgrw1m","What is the cause of red urine without RBCs on microscopy?","Myoglobin, hemoglobin, beets, rifampin, phenazopyridine, porphyria.","Mioglobina, hemoglobina, beterraba."],["1njpydky4","What is nephrocalcinosis?","Calcium deposition in renal parenchyma (hyperparathyroidism, RTA type 1, medullary sponge kidney).","Depósito de cálcio no rim."],["1m0di92aj","What is renal tuberculosis's classic urine finding?","Sterile pyuria.","Piúria estéril."],["xq3f161ex","What is the renal involvement of sarcoidosis?","Hypercalcemia, nephrocalcinosis, granulomatous interstitial nephritis.","Hipercalcemia e nefrite granulomatosa."],["13rhx15ur","What is the renal involvement of Sjögren syndrome?","Distal (type 1) RTA and tubulointerstitial nephritis.","Acidose tubular distal."],["1764khy18","What is the renal involvement of scleroderma?","Scleroderma renal crisis (hypertension, AKI); treat with ACE inhibitors.","Crise renal; IECA."],["18ehwk317","What is the renal involvement of HUS?","Thrombotic microangiopathy causing AKI.","Microangiopatia trombótica."],["1nih92vsa","What is the renal involvement of preeclampsia?","Glomerular endotheliosis and proteinuria.","Endoteliose glomerular."]]},{"name":"Pharmacology","cards":[["1dnu2saxz","Mechanism of mannitol?","Osmotic diuretic: increases tubular fluid osmolarity, increasing urine flow.","Diurético osmótico."],["1z80xd3q2","Uses of mannitol?","Drug overdose, elevated intracranial or intraocular pressure.","Hipertensão intracraniana."],["9d3dlj12q","Adverse effects of mannitol?","Pulmonary edema, dehydration, hypo- or hypernatremia; contraindicated in anuria and heart failure.","Edema pulmonar e desidratação."],["z2anif1fe","Mechanism of acetazolamide?","Carbonic anhydrase inhibitor in PCT, causing self-limited NaHCO3 diuresis and decreased total body HCO3-.","Inibe a anidrase carbônica."],["qoeafg89r","Uses of acetazolamide?","Glaucoma, metabolic alkalosis, altitude sickness, idiopathic intracranial hypertension, urinary alkalinization.","Glaucoma, altitude, pseudotumor."],["ilj2967al","Adverse effects of acetazolamide?","Hyperchloremic metabolic acidosis, paresthesias, NH3 toxicity, sulfa allergy, calcium phosphate stones.","Acidose e parestesias."],["r36ot21tu","Mechanism of loop diuretics?","Inhibit NKCC2 cotransporter in the thick ascending limb, abolishing hypertonicity of the medulla; increase prostaglandins (dilate afferent arteriole).","Inibem o NKCC2."],["5kglx21o0","Examples of loop diuretics?","Furosemide, bumetanide, torsemide (sulfonamides), ethacrynic acid (non-sulfonamide).","Furosemida e bumetanida."],["1nbqxtpyb","Uses of loop diuretics?","Edematous states (heart failure, cirrhosis, nephrotic syndrome, pulmonary edema), hypertension, hypercalcemia.","Edema e hipercalcemia."],["93807vx5c","Adverse effects of loop diuretics?","Ototoxicity, hypokalemia, hypomagnesemia, dehydration, allergy (sulfa), metabolic alkalosis, nephritis (interstitial), gout (OH DAMMIT).","Ototoxicidade, hipocalemia, gota."],["g5av1o1l1","Why do NSAIDs reduce loop diuretic efficacy?","They block prostaglandin-mediated afferent vasodilation.","Bloqueiam as prostaglandinas."],["10dzyg8d7","When is ethacrynic acid used?","Diuresis in patients allergic to sulfa drugs; more ototoxic.","Alergia a sulfa."],["uwn37wylq","Mechanism of thiazide diuretics?","Inhibit NaCl reabsorption in early DCT (NCC), decreasing diluting capacity; decrease Ca2+ excretion.","Inibem o NCC."],["1nka3fwdf","Examples of thiazide diuretics?","Hydrochlorothiazide, chlorthalidone, metolazone, indapamide.","Hidroclorotiazida e clortalidona."],["1ap255z17","Uses of thiazide diuretics?","Hypertension, heart failure, idiopathic hypercalciuria, nephrogenic DI, osteoporosis.","Hipertensão e cálculos de cálcio."],["vejrgwjv8","Adverse effects of thiazides?","Hypokalemic metabolic alkalosis, hyponatremia, hyperglycemia, hyperlipidemia, hyperuricemia, hypercalcemia, sulfa allergy (hyperGLUC).","Hiponatremia, hiperglicemia, hiperuricemia, hipercalcemia."],["w7rub414f","Why do thiazides paradoxically treat nephrogenic diabetes insipidus?","Mild volume depletion increases PCT sodium and water reabsorption, reducing urine output.","Depleção leve reduz a diurese."],["1xhs0nmrf","What is the role of metolazone with loop diuretics?","Sequential nephron blockade for diuretic resistance.","Bloqueio sequencial."],["8tv74c10h","Mechanism of potassium-sparing diuretics?","Spironolactone and eplerenone: aldosterone receptor antagonists. Amiloride and triamterene: block ENaC in collecting duct.","Antagonistas da aldosterona ou bloqueiam ENaC."],["1jkm687t9","Uses of potassium-sparing diuretics?","Hyperaldosteronism, potassium depletion, heart failure (spironolactone, eplerenone reduce mortality), hepatic ascites, nephrogenic DI from lithium (amiloride), Liddle syndrome (amiloride).","Hiperaldosteronismo e insuficiência cardíaca."],["1shcbj51o","Adverse effects of potassium-sparing diuretics?","Hyperkalemia (arrhythmias), endocrine effects with spironolactone (gynecomastia, antiandrogen).","Hipercalemia e ginecomastia."],["11hgbrmsn","Why is amiloride used for lithium-induced nephrogenic DI?","Blocks ENaC, preventing lithium entry into principal cells.","Impede a entrada de lítio."],["c2c2381tx","What are the effects of diuretics on urine NaCl?","Increased by all diuretics except acetazolamide (serum NaCl may decrease).","Aumentam sódio urinário."],["1ua3ies1n","What are the effects of diuretics on urine K+?","Increased with loop and thiazides (decreased with K-sparing).","Alça e tiazídico perdem potássio."],["k52ov31dk","Which diuretics cause metabolic alkalosis?","Loop and thiazides (volume contraction, K+ loss, increased H+ secretion).","Alça e tiazídicos."],["rx85bvrwm","Which diuretics cause metabolic acidosis?","Carbonic anhydrase inhibitors and potassium-sparing diuretics.","Acetazolamida e poupadores de potássio."],["c5uqq71tv","What are the effects of diuretics on urine Ca2+?","Loop diuretics increase calcium excretion; thiazides decrease it.","Alça aumenta; tiazídico diminui."],["w416361il","Mechanism of ACE inhibitors in the kidney?","Decrease angiotensin II, dilating efferent arteriole, reducing intraglomerular pressure and proteinuria.","Dilatam a eferente; reduzem proteinúria."],["2p5m181aj","What renal effect occurs when starting ACE inhibitors?","Mild increase in creatinine (acceptable up to 30%); larger increase suggests renal artery stenosis.","Creatinina sobe um pouco."],["1snq8wl13","Why are ACE inhibitors used in diabetic nephropathy?","Slow progression by reducing glomerular hypertension and proteinuria.","Protegem o rim do diabético."],["1profwg1l","Mechanism of ARBs in the kidney?","Block AT1 receptors, similar renal protective effects as ACE inhibitors without increasing bradykinin.","Bloqueiam o receptor AT1."],["18kald817","Mechanism and use of aliskiren?","Direct renin inhibitor; hypertension; avoid combining with ACE inhibitors/ARBs in diabetics.","Inibidor direto da renina."],["1kcwlz61t","Mechanism and use of SGLT2 inhibitors in CKD?","Reduce intraglomerular pressure via tubuloglomerular feedback; slow CKD progression and reduce cardiovascular events.","Protegem o rim."],["1nlr43d1x","Mechanism and use of finerenone?","Nonsteroidal mineralocorticoid receptor antagonist; diabetic CKD to reduce progression.","Antagonista mineralocorticoide."],["189nowmoj","Mechanism and use of tolvaptan in ADPKD?","V2 antagonist slowing cyst growth; hepatotoxicity risk.","Reduz cistos; hepatotoxicidade."],["eca9o7iaj","Mechanism and use of conivaptan?","V1a and V2 antagonist; euvolemic and hypervolemic hyponatremia (IV).","Hiponatremia."],["ttk1741iq","Mechanism and use of desmopressin?","V2 agonist; central DI, nocturnal enuresis, hemophilia A and von Willebrand disease.","Diabetes insípido central."],["1uirlguc5","Mechanism and use of demeclocycline in SIADH?","Tetracycline that blocks ADH action in collecting duct (nephrogenic DI).","Bloqueia a ação do ADH."],["c9cf4i1pk","Mechanism and use of sevelamer?","Nonabsorbable phosphate binder (non-calcium); hyperphosphatemia in CKD.","Quelante de fósforo."],["zsn2kg1ku","Mechanism and use of calcium acetate and calcium carbonate in CKD?","Bind dietary phosphate; risk of hypercalcemia and vascular calcification.","Quelantes com cálcio."],["1kv1lgy1l","Mechanism and use of cinacalcet in CKD?","Calcimimetic sensitizing calcium-sensing receptor, lowering PTH in secondary hyperparathyroidism.","Reduz PTH."],["1gg1b8ddy","Mechanism and use of erythropoiesis-stimulating agents?","Epoetin alfa and darbepoetin stimulate RBC production; anemia of CKD; risk of hypertension, thrombosis, stroke if Hb target too high.","Anemia da doença renal."],["amz6ap1l7","What is the hemoglobin target in CKD with ESAs?","Avoid exceeding about 11.5 g/dL (increased cardiovascular risk).","Não passar de 11,5."],["14uoch9pn","Mechanism and use of patiromer and sodium zirconium cyclosilicate?","Potassium binders in the gut; chronic hyperkalemia.","Quelantes de potássio."],["1x4berg1k","Mechanism and use of sodium polystyrene sulfonate?","Cation exchange resin binding K+ in the colon; risk of intestinal necrosis.","Resina de troca; risco intestinal."],["inqtqig14","Mechanism and use of sodium bicarbonate in CKD?","Treats metabolic acidosis, may slow CKD progression.","Corrige a acidose."],["1ef5ibr1s","Mechanism and use of potassium citrate?","Alkalinizes urine and binds calcium; prevents calcium oxalate, uric acid, and cystine stones.","Alcaliniza a urina."],["1eclsied3","Mechanism and use of tamsulosin for kidney stones?","Alpha1A blocker relaxing ureteral smooth muscle, facilitating stone passage (medical expulsive therapy).","Ajuda a eliminar o cálculo."],["12lbbmqa0","What analgesic is first line for renal colic?","NSAIDs (ketorolac), opioids if needed.","AINEs."],["1q8nnrv5q","What drugs prevent uric acid stones?","Allopurinol, potassium citrate (alkalinization).","Alopurinol e citrato."],["1qaf0hy1i","What drugs prevent cystine stones?","Alkalinization, high fluids, tiopronin or penicillamine.","Tiopronina."],["tvly1b6r1","What drug treats struvite stones?","Surgical removal, antibiotics, acetohydroxamic acid (urease inhibitor).","Remoção e antibiótico."],["122mep91u","What drug is used for overactive bladder in elderly to avoid anticholinergic effects?","Mirabegron (beta3 agonist).","Mirabegrona."],["70o9oh1yi","Which drugs are nephrotoxic?","Aminoglycosides, vancomycin, amphotericin B, cisplatin, NSAIDs, contrast, cyclosporine, tacrolimus, acyclovir, foscarnet, cidofovir, lithium.","Drogas nefrotóxicas."],["1g4lacrpg","Which drugs cause acute interstitial nephritis?","Penicillins, cephalosporins, NSAIDs, PPIs, rifampin, sulfonamides, diuretics, allopurinol.","Penicilinas, AINEs, IBP."],["h63uqx19q","Which drugs cause crystal nephropathy?","Acyclovir, sulfonamides, methotrexate, indinavir, ethylene glycol (oxalate).","Aciclovir e metotrexato."],["pcy7d71bo","Which drugs reduce renal perfusion?","NSAIDs, ACE inhibitors, ARBs, calcineurin inhibitors, diuretics (volume depletion).","AINEs e IECA."],["ok7hrw80t","Which drugs increase creatinine without affecting GFR?","Trimethoprim, cimetidine, dolutegravir (block tubular secretion).","Trimetoprima e cimetidina."],["1j2i0901x","Which drugs require dose adjustment in CKD?","Metformin, gabapentin, enoxaparin, DOACs, many antibiotics, digoxin, lithium.","Metformina e enoxaparina."],["9fv9zb7zl","Which drugs are contraindicated in severe CKD?","Metformin (eGFR <30), NSAIDs, gadolinium (nephrogenic systemic fibrosis), magnesium-containing laxatives.","Metformina e gadolínio."],["1ob30vo11","What is nephrogenic systemic fibrosis?","Skin and organ fibrosis after gadolinium contrast in severe CKD.","Fibrose após gadolínio."],["1wt4l8ngz","How is contrast nephropathy prevented?","IV isotonic saline hydration, minimize contrast volume, hold nephrotoxins.","Hidratação."],["f9x2b41il","What is the treatment of hyperkalemia with ECG changes first step?","IV calcium gluconate (membrane stabilization).","Gluconato de cálcio."],["1gdgg5em1","Which drugs shift potassium into cells?","Insulin with glucose, beta2 agonists (albuterol), sodium bicarbonate.","Insulina e salbutamol."],["1qrdbua1x","Which drug removes potassium from the body?","Loop diuretics, potassium binders, dialysis.","Diuréticos e diálise."],["wdy57ghci","Which diuretic is used for hypertension in a patient with osteoporosis?","Thiazide (decreases calcium excretion).","Tiazídico."],["p91co8172","Which diuretic is used for hypertension with hypokalemia?","Potassium-sparing diuretic (spironolactone) or combination.","Espironolactona."],["1k1692p1u","Which diuretic is used for acute pulmonary edema?","IV furosemide.","Furosemida venosa."],["1qck92x3i","Which diuretic is used for cirrhotic ascites?","Spironolactone plus furosemide (ratio 100:40).","Espironolactona com furosemida."],["zygq961qm","Which diuretic is used for primary hyperaldosteronism?","Spironolactone or eplerenone.","Espironolactona."],["mzp0cxi3t","Which diuretic is used in glaucoma and altitude sickness?","Acetazolamide.","Acetazolamida."],["1sd3q7ez8","Which diuretic is used to reduce ICP?","Mannitol (or hypertonic saline).","Manitol."],["afdcam18c","Which diuretic worsens gout?","Thiazides and loop diuretics (hyperuricemia).","Tiazídicos e de alça."],["15i2thl1x","Which diuretic causes hearing loss with aminoglycosides?","Loop diuretics.","Diurético de alça."],["1smp5n91c","Which diuretic class is associated with sulfa allergy?","Loop (except ethacrynic acid), thiazides, acetazolamide.","Alça, tiazídicos, acetazolamida."],["15fixemke","Which diuretic causes gynecomastia?","Spironolactone (use eplerenone instead).","Espironolactona."],["1w6fnbz19","What drug is used to treat nephrogenic DI from lithium?","Amiloride.","Amilorida."],["l0u11m11z","What drug is used to treat central DI?","Desmopressin.","Desmopressina."],["irv06h1ph","What drug is used for SIADH refractory to fluid restriction?","Tolvaptan, conivaptan, salt tablets, demeclocycline.","Tolvaptana."],["1d7fn59en","What drug is used for hypertensive emergency with renal failure?","Fenoldopam or clevidipine/nicardipine.","Fenoldopam."],["3afck31qm","What is the dialysis-related drug consideration?","Highly protein-bound or large Vd drugs are poorly removed by dialysis.","Ligados a proteínas não são dialisados."],["2mx3e0vqg","What immunosuppressants are used after kidney transplant?","Tacrolimus, mycophenolate, corticosteroids (induction with basiliximab or antithymocyte globulin).","Tacrolimo, micofenolato e corticoide."],["xloue1e5v","What is the major side effect of calcineurin inhibitors on the kidney?","Nephrotoxicity (afferent arteriole vasoconstriction, interstitial fibrosis).","Nefrotoxicidade."],["i0dbd71bh","Which antiviral is used for BK virus nephropathy?","Reduce immunosuppression (no specific antiviral; cidofovir or leflunomide sometimes).","Reduzir a imunossupressão."],["gli1zkhff","What is the mechanism of probenecid on penicillin?","Inhibits renal tubular secretion of penicillin, increasing its levels.","Aumenta nível da penicilina."],["j55btlrls","What is the mechanism of NSAID-induced hyperkalemia?","Decreased renin and aldosterone (hyporeninemic hypoaldosteronism).","Reduz renina e aldosterona."],["1joknwho1","What is the mechanism of heparin-induced hyperkalemia?","Inhibits aldosterone synthesis.","Inibe a aldosterona."],["zupa9m1e9","What is the mechanism of trimethoprim-induced hyperkalemia?","Blocks ENaC in the collecting duct (like amiloride).","Bloqueia o ENaC."],["12xzqka17","What is the mechanism of calcineurin inhibitor hyperkalemia?","Decreased aldosterone effect and ENaC activity (type 4 RTA-like).","Efeito tipo ATR 4."],["1szu09b1k","What is the mechanism of amphotericin B renal toxicity?","Distal tubular damage causing type 1 RTA, hypokalemia, hypomagnesemia.","Lesão tubular distal."],["1g4bak91e","What is the mechanism of aminoglycoside renal toxicity?","Accumulation in proximal tubular cells causing ATN (nonoliguric).","Necrose tubular proximal."],["k7gl8vhrk","What is the mechanism of cisplatin renal toxicity?","PCT injury, hypomagnesemia; prevent with amifostine and hydration.","Lesão proximal; hipomagnesemia."],["1qokgmh9y","What is the mechanism of ifosfamide renal toxicity?","Fanconi syndrome and hemorrhagic cystitis.","Síndrome de Fanconi."],["xur3vwrx6","What is the mechanism of tenofovir renal toxicity?","Fanconi syndrome (PCT dysfunction); TAF is less nephrotoxic.","Fanconi; TAF é mais seguro."],["1vontv2al","What is the mechanism of acyclovir renal toxicity?","Crystal nephropathy (obstructive); prevent with hydration.","Cristais; hidratação."],["1r7f0jsg5","What is the mechanism of methotrexate renal toxicity?","Precipitation in tubules (high dose); prevent with hydration and urine alkalinization.","Precipita nos túbulos."],["yflbb21dm","What is the treatment of diuretic-induced hypokalemia?","Potassium supplementation or add potassium-sparing diuretic.","Repor potássio."],["1kt0qn75i","What is the mechanism of loop diuretics in hypercalcemia?","Increase calcium excretion after volume repletion with saline.","Aumentam excreção de cálcio após hidratação."]]}];
